const select=document.getElementById('languageSelect');
function applyLanguage(lang){const dict=T[lang]||T.en;document.documentElement.lang=lang;document.documentElement.dir=directions[lang]||'ltr';document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(dict[key])el.textContent=dict[key];});if(select)select.value=lang;try{localStorage.setItem('saharPortfolioLanguage',lang)}catch(e){}}
if(select){let saved='en';try{saved=localStorage.getItem('saharPortfolioLanguage')||'en'}catch(e){}applyLanguage(T[saved]?saved:'en');select.addEventListener('change',e=>applyLanguage(e.target.value));}
